class KindelSubjekt implements Subjekt {
    public olek: number;

    private jalgijad: Jalgija[] = [];

    public attach(jalgija: Jalgija): void {
        const onOlemas = this.jalgijad.includes(jalgija);
        if (onOlemas) {
            return console.log("Subjekt: jalgija on juba registreeritud")
        }
        this.jalgijad.push(jalgija);
    }

    public detach(jalgija: Jalgija): void {
        const jalgijaIndeks = this.jalgijad.indexOf(jalgija);
        
        if (jalgijaIndeks === -1) {
            return console.log("Subjekt: jalgijat ei leitud");
        }

        this.jalgijad.splice(jalgijaIndeks, 1);
        console.log("subjekt: jalgija mõrvati");
    }

    public teavita(): void {
        console.log("Subjekt: teavitan jalgijaid");
        for (const jalgija of this.jalgijad) {
            jalgija.uuendaMind(this);
        }
    }

    public mingiAriloogika(): void {
        console.log("Subjekt: mingi vark laks baltas lahti");
        this.olek = Math.floor(Math.random() * (10 + 1))
        console.log(`Subjekt: mu olek on nyyd: ${this.olek}`);
        this.teavita();
    }

}

interface Jalgija {
    uuendaMind(subjekt: Subjekt): void
}


class KindelKuualajaA implements Jalgija {
    public uuendaMind(subjekt: Subjekt): void {
        if (subjekt instanceof KindelSubjekt && subjekt.olek < 3) {
            console.log('KindeljalgijaA reageeris juhtumile')
        }
    }
}
